#!/usr/bin/env node
// Generates supabase/recovery/*.sql from supabase/recovery/src/.
// Every generated file embeds the SAME reconciliation core, so the report,
// the preview and the execute script can never classify differently.
//   node scripts/build-recovery-sql.mjs          → write files
//   node scripts/build-recovery-sql.mjs --check  → exit 1 if files are stale
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..', 'supabase', 'recovery');
const src = (f) => readFileSync(join(root, 'src', f), 'utf8');
const core = src('core.sql');

const READONLY = `-- READ-ONLY: creates session TEMP tables only. Safe to run in production.
-- Supabase SQL Editor shows the result of the LAST statement.
`;
const targets = [
  ['01_reconciliation_report.sql', 'Full reconciliation per student / month / currency', READONLY, '01_reconciliation_report.tail.sql'],
  ['02_reconciliation_summary.sql', 'Summary counts and amounts by month / currency / category', READONLY, '02_reconciliation_summary.tail.sql'],
  ['03_start_date_restore_preview.sql', 'Students with a missing tuition_start_date and the proposed restore value', READONLY, '03_start_date_restore_preview.tail.sql'],
  ['04_recovery_plan_preview.sql', 'DRY RUN — exact rows the recovery would insert + approval hash', READONLY, '04_recovery_plan_preview.tail.sql'],
  ['05_recovery_execute.sql', 'EXECUTE recovery of category-A transactions (requires approval)', null, '05_recovery_execute.tail.sql', '05_recovery_execute.head.sql'],
  ['06_start_date_restore_execute.sql', 'EXECUTE restore of category-A start dates (requires approval)', null, '06_start_date_restore_execute.tail.sql', '06_start_date_restore_execute.head.sql'],
];

let stale = false;
for (const [out, title, preface, tail, head] of targets) {
  const content =
    `-- ============================================================\n` +
    `-- ${out} — ${title}\n` +
    `-- GENERATED by scripts/build-recovery-sql.mjs from supabase/recovery/src/ — DO NOT EDIT\n` +
    `-- ============================================================\n` +
    (preface ?? '') + '\n' +
    (head ? src(head) + '\n' : '') +
    core + '\n' + src(tail);
  const path = join(root, out);
  if (process.argv.includes('--check')) {
    if (!existsSync(path) || readFileSync(path, 'utf8') !== content) {
      console.error(`stale: ${out}`);
      stale = true;
    }
  } else {
    writeFileSync(path, content);
    console.log(`wrote ${out}`);
  }
}
if (stale) process.exit(1);
